window.MOTIF_CATALOG_CHUNKS[7]={"cards":[{"id":"MEJE-KW-000781","row_version":1,"title":"원작의 잘못을 따져 묻는 팬픽","original":"Accusation Fic","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"원작에서 인물이 저지른 일이나 이야기의 판단을 팬이 다시 검토하고 책임을 묻는 방향으로 쓰는 2차 창작. 비판 대상과 결과를 어떻게 그리는지에 따라 수정 서사와 복수 서사 사이를 오갈 수 있다. 팬픽 매체 안의 한 구성 방식이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-000781/index.html"},{"id":"MEJE-KW-000782","row_version":1,"title":"뉘우치는 사람에게 죄책감을 계속 강요하기","original":"Accuser of the Brethren","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"과거의 잘못을 인정하고 바꾸려는 인물에게 다른 인물이 거듭 비난을 들이밀어 관계 회복을 막는 구도. 사과를 받아들일 의무와 변화한 사람을 평가할 기준은 별개의 문제로 남는다. 막을 수 있었는데 외면했다고 비난받기는 행동하지 않은 책임을 둘러싼 다른 갈등이다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-000782/index.html"},{"id":"MEJE-KW-000783","row_version":1,"title":"증인을 범인으로 몰아 의심 만들기","original":"Accuse the Witness","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"재판 장면에서 증언하던 사람을 사건의 범인으로 지목해 기존 혐의에 의문을 만드는 전개. 지목이 사실인지와 인물이 의심을 만들기 위해 말했는지를 구분해야 한다. 무죄 인정이 너무 늦게 오기는 판단이 뒤늦게 뒤집힌 결과를 다룬다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-000783/index.html"},{"id":"MEJE-KW-000784","row_version":1,"title":"에이스를 위해 맞춘 전용 장비","original":"Ace Custom","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"기량이 뛰어난 사용자의 전투 방식에 맞게 일반 모델을 고쳐 만든 기계나 무기. 성능 차이뿐 아니라 그 장비를 다룰 수 있는 사람의 정체성을 보여준다. 뛰어난 비행 전투 조종사에게 전용 기체가 주어질 수 있다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-000784/index.html"},{"id":"MEJE-KW-000785","row_version":1,"title":"뛰어난 비행 전투 조종사","original":"Ace Pilot","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"하늘이나 우주에서 기체의 한계를 끌어내며 작전의 흐름을 바꾸는 조종사 인물형. 실전 능력과 팀 안의 역할을 구분해 그린다. 에이스를 위해 맞춘 전용 장비는 이런 인물의 기술을 강조하는 사물이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000785/index.html"},{"id":"MEJE-KW-000786","row_version":1,"title":"지난 상처가 다시 아픈 듯 느껴지기","original":"Achey Scars","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"과거의 상처 자국이 옛 적이나 사건을 만난 순간 다시 아픈 듯 표현되는 상징 장면. 몸의 반응으로 기억과 두려움을 드러내는 서사 표현이다. 신체 능력처럼 현재의 힘을 설명하는 카드와 구분한다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-000786/index.html"},{"id":"MEJE-KW-000787","row_version":1,"title":"실패를 비웃는 업적 보상","original":"Achievement Mockery","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임이 실수·무의미한 행동·나쁜 결과에도 업적을 주면서 플레이어를 놀리는 보상 방식. 성취 기록이 칭찬이 아니라 농담이 된다. 업적을 기록하는 게임 시스템 안에서 업적 문구의 태도가 달라진 경우다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-000787/index.html"},{"id":"MEJE-KW-000788","row_version":1,"title":"불가능한 줄 몰라 해낸 일","original":"Achievements in Ignorance","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 어려움이나 금기를 모른 채 행동해 주변이 불가능하다고 여긴 결과를 이루는 사건. 무지가 기술의 대체물이라기보다 시도 자체를 막던 기대를 치운다. 그네를 한 바퀴 넘기려는 도전이 뜻밖의 성공으로 이어지는 경우와 닮았다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-000788/index.html"},{"id":"MEJE-KW-000789","row_version":1,"title":"업적을 기록하는 게임 시스템","original":"Achievement System","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임이 본편의 진행과 별도로 플레이어의 행동과 목표 달성을 목록에 기록하는 장치. 비공개 업적과 보상 방식에 따라 탐색의 방향이 달라진다. 게임의 모든 과제를 끝내는 100% 달성은 이 목록을 채우는 목표가 될 수 있다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-000789/index.html"},{"id":"MEJE-KW-000790","row_version":1,"title":"한 번의 시험이 미래를 결정하는 세계","original":"Achievement Test of Destiny","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"시험 한 번의 결과가 진로와 지위를 거의 확정한다고 여기는 사회 설정. 인물이 느끼는 압박은 점수 자체보다 다른 길을 허용하지 않는 제도에서 나온다. 성취 욕구는 인물의 내적 동기로 이 사회 규칙과 구분된다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-000790/index.html"},{"id":"MEJE-KW-000791","row_version":1,"title":"강한 존재에게 남은 결정적 약점","original":"Achilles' Heel","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"거의 이길 수 없어 보이는 존재에게 특정 조건이나 지점에서만 드러나는 취약성이 있는 설정. 약점의 발견과 이용이 힘의 차이를 뒤집는다. 상성 약점은 그 취약성이 상대의 성질과 맞물린 경우다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-000791/index.html"},{"id":"MEJE-KW-000792","row_version":1,"title":"떠난 동료가 위기 때 돌아오기","original":"Achilles in His Tent","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"갈등으로 팀을 떠난 인물이 남은 동료의 위험을 보고 마지막 순간 다시 합류하는 전개. 돌아오는 선택이 관계 회복의 증거가 된다. 포기했다가 곧 돌아오는 주인공은 팀 탈퇴보다 활동 포기에 초점을 둔다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-000792/index.html"},{"id":"MEJE-KW-000793","row_version":1,"title":"전원선 하나에 묶인 강력한 기계","original":"Achilles' Power Cord","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"큰 힘을 가진 기계가 외부 전원선에 의존해 선이 끊기거나 길이가 모자라면 무력해지는 약점. 강한 본체와 사소한 연결부의 대비가 반전이나 웃음을 만든다. 강한 존재에게 남은 결정적 약점의 기계적 사례다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-000793/index.html"},{"id":"MEJE-KW-000794","row_version":1,"title":"산성 물질을 내뿜는 능력","original":"Acid Attack","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"생물이나 인물이 산성 물질을 분사하거나 다루어 공격과 방어에 쓰는 허구의 능력. 효과의 범위와 방어 방법은 작품의 힘 체계가 정한다. 산성 액체 웅덩이를 장애물로 쓰기는 능력자가 아니라 공간에 놓인 위험이다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000794/index.html"},{"id":"MEJE-KW-000795","row_version":1,"title":"산성 액체 웅덩이를 장애물로 쓰기","original":"Acid Pool","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"통로 아래나 실험 시설에 놓인 산성 액체의 웅덩이가 이동과 탈출을 막는 공간 장치. 색과 거품 같은 시각 표지가 위험을 빠르게 알린다. 산성 물질을 내뿜는 능력은 움직이는 사용자가 힘을 쓰는 경우다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-000795/index.html"},{"id":"MEJE-KW-000796","row_version":1,"title":"먹은 음식 탓으로 돌리는 악몽","original":"Acid Reflux Nightmare","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"이상한 꿈을 꾼 인물이 음식을 많이 먹었거나 속이 불편해서 생긴 일이라고 설명하는 장면. 꿈의 의미를 회피하거나 환상적 사건의 진실을 미루는 말이 될 수 있다. 꿈의 세계가 실제로 존재하는 설정과는 다를 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-000796/index.html"},{"id":"MEJE-KW-000797","row_version":1,"title":"소음 속에서도 대사가 선명하게 들리기","original":"Acoustic License","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"큰 소음이 있는 장소에서도 인물끼리 중요한 말을 거리낌 없이 주고받고 관객도 또렷이 듣는 음향 관습. 실제 공간의 소리 조건보다 대사의 전달을 우선한다. 중요한 말에만 주변 소리가 멎기는 소음을 갑자기 없애는 다른 방식이다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-000797/index.html"},{"id":"MEJE-KW-000798","row_version":1,"title":"아는 사람을 모른 척하기","original":"Acquaintance Denial","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"창피함이나 불이익을 피하려고 가까운 사람을 공개된 자리에서 모른다고 하는 관계 행동. 부정당한 사람이 이를 알아차리는 순간 친밀감의 균열이 드러난다. 익명으로 만난 상대가 이미 아는 사람은 상대의 정체를 처음에 모르는 상황이다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-000798/index.html"},{"id":"MEJE-KW-000799","row_version":1,"title":"익명으로 만난 상대가 이미 아는 사람","original":"Acquainted in Real Life","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"편지나 온라인의 익명 관계에서 가까워진 상대가 현실에서 이미 알고 지내던 사람으로 밝혀지는 전개. 두 관계의 정보가 합쳐지면서 친밀감이나 갈등의 뜻이 바뀐다. 아는 사람을 모른 척하기는 정체를 알면서 공개적으로 부정하는 경우다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-000799/index.html"},{"id":"MEJE-KW-000800","row_version":1,"title":"신고만 해도 알아보는 구조 대원들","original":"Acquainted with Emergency Services","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"사고나 소동이 잦은 인물을 구조 인력이나 신고 접수자가 이미 이름으로 알아보는 반복 관계. 낯선 공적 절차가 오래된 인연처럼 보이며 웃음이나 걱정을 만든다. 아는 사람을 모른 척하기와 달리 서로 알아본다는 사실이 장면의 핵심이다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-000800/index.html"},{"id":"MEJE-KW-000801","row_version":1,"title":"새 힘과 함께 생긴 약점","original":"Acquired Achilles' Heel","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"능력이나 새로운 몸을 얻은 대가로 이전에는 없던 취약성도 함께 갖게 되는 설정. 힘의 획득이 곧 위험의 획득이므로 선택의 비용이 분명해진다. 강한 존재에게 남은 결정적 약점은 선천적이거나 원래부터 있던 약점도 포함한다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000801/index.html"},{"id":"MEJE-KW-000802","row_version":1,"title":"인쇄물의 작은 오타가 뜻을 바꾸기","original":"Acquired Error at the Printer","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"포스터나 표지의 글자 하나가 잘못 인쇄되어 원래 의도와 다른 우스운 문장이 되는 장면. 공개되기 전 확인하지 못한 실수가 인물의 체면이나 사건을 흔든다. 약어를 서로 헷갈리기는 인쇄 오류가 아니라 해석 오류다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-000802/index.html"},{"id":"MEJE-KW-000803","row_version":1,"title":"독에 익숙해진 인물","original":"Acquired Poison Immunity","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"작품에서 독에 오래 노출된 인물이 특정 독에는 끄떡없다는 설정. 상대가 예상한 위험이 통하지 않으며 준비 기간이 반전으로 드러날 수 있다. 마법 효과에 강한 저항력은 독이 아니라 주문에 대한 반응이다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000803/index.html"},{"id":"MEJE-KW-000804","row_version":1,"title":"갑작스러운 성공 뒤 우쭐해지기","original":"Acquired Situational Narcissism","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"주목과 성과를 얻은 인물이 자신을 지나치게 높이 평가하고 가까운 사람을 소홀히 하는 변화. 관심이 사라진 뒤 관계가 어떻게 남는지가 후속 이야기다. 잠깐 쏟아졌다 사라지는 유명세는 이런 변화의 계기가 될 수 있다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-000804/index.html"},{"id":"MEJE-KW-000805","row_version":1,"title":"무죄 인정이 너무 늦게 오기","original":"Acquitted Too Late","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"누명을 벗길 사실이나 판단이 드러났지만 이미 돌이킬 수 없는 손실이 일어난 뒤인 비극적 결말. 진실의 회복과 피해의 회복이 같은 일이 아님을 보여준다. 증인을 범인으로 몰아 의심 만들기는 재판 중 의심의 방향을 바꾸는 전개다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-000805/index.html"},{"id":"MEJE-KW-000806","row_version":1,"title":"큰 체격에도 빠르고 민첩한 인물","original":"Acrofatic","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"크고 무거워 보이는 인물이 빠른 움직임과 유연한 동작으로 주변의 선입견을 깨는 인물 표현. 민첩함을 놀라움으로만 쓰지 않고 인물의 실제 기술로 그릴 수도 있다. 신체 능력은 몸의 움직임을 넓게 찾는 태그다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000806/index.html"},{"id":"MEJE-KW-000807","row_version":1,"title":"약어가 너무 많아 대화가 어려워지기","original":"Acronym and Abbreviation Overload","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"집단 안의 줄임말과 머리글자어가 잇달아 나와 바깥 사람이 말을 따라가기 어렵게 되는 언어 관습. 효율을 위해 만든 말이 정보의 장벽이 된다. 약어를 서로 헷갈리기는 개수가 아니라 뜻을 잘못 짚는 경우다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-000807/index.html"},{"id":"MEJE-KW-000808","row_version":1,"title":"약어를 서로 헷갈리기","original":"Acronym Confusion","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"비슷한 머리글자어나 줄임말의 뜻을 바꾸어 받아들여 엉뚱한 말을 하거나 행동하는 장면. 같은 기호에 여러 뜻이 있을수록 오해가 커진다. 약어를 보통 단어처럼 잘못 읽기는 뜻보다 발음과 표기의 착오다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-000808/index.html"},{"id":"MEJE-KW-000809","row_version":1,"title":"약어를 보통 단어처럼 잘못 읽기","original":"Acronyms Are Easy as Aybeecee","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"머리글자를 하나씩 읽어야 할 표기를 낱말처럼 발음하거나, 들은 철자 이름을 하나의 낱말로 적는 말장난. 소리와 글자 단위의 경계가 어긋난다. 약어를 서로 헷갈리기는 서로 다른 약어의 뜻을 바꾸어 아는 경우다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-000809/index.html"},{"id":"MEJE-KW-000810","row_version":1,"title":"날 수 있는데 달아날 때 잊기","original":"Acrophobic Bird","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"비행할 수 있는 인물이 추격을 받으면서도 위로 날지 않고 달리거나 같은 높이로만 도망치는 연출 관습. 위험을 유지하려는 장면의 필요가 능력의 활용을 제한한다. 비행 능력 자체의 부재와는 구별한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-000810/index.html"},{"id":"MEJE-KW-000811","row_version":1,"title":"광고 전환에 맞춰 끊는 막 구성","original":"Act Break","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":null,"parent_id":null,"tag_path":["ML-F04"],"summary":"방송 이야기를 몇 막으로 나누고 막의 끝에서 잠깐의 중단이나 광고를 받을 수 있게 긴장을 배치하는 형식. 막 경계가 다음 장면을 궁금하게 만드는 단위가 된다. 극중 방송도 같은 방송 형식을 작품 안의 장면으로 보여줄 수 있다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"분류축","entry_url":"cards/MEJE-KW-000811/index.html"},{"id":"MEJE-KW-000812","row_version":1,"title":"한 배우가 여러 배역 맡기","original":"Acting for Two","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"한 작품에서 같은 배우가 닮은 사람이나 전혀 다른 인물 등 둘 이상의 역할을 연기하는 제작 방식. 관객이 닮음을 알아차리게 할지 숨길지에 따라 장면의 뜻이 바뀐다. 배우가 뒤의 전개를 모른 채 연기하기는 배역 수가 아니라 배우에게 제공된 정보의 문제다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-000812/index.html"},{"id":"MEJE-KW-000813","row_version":1,"title":"배우가 뒤의 전개를 모른 채 연기하기","original":"Acting in the Dark","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"배우가 자신의 인물에 관한 뒤의 반전이나 장면 맥락을 모르는 상태에서 연기하는 제작 조건. 그 무지가 자연스러운 반응을 만들 수도 있고 연속성 조정을 어렵게 할 수도 있다. 한 배우가 여러 배역 맡기는 정보가 아니라 배역의 수에 관한 방식이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-000813/index.html"},{"id":"MEJE-KW-000814","row_version":1,"title":"상상을 실제 행동으로 옮겨 버리기","original":"Acting Out a Daydream","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"공상에 깊이 빠진 인물이 상상 속 행동을 현실 몸짓으로 따라 해 주변을 당황하게 하는 사건. 관객에게 먼저 상상을 보여주면 현실 장면과의 차이가 웃음이 된다. 꿈의 세계처럼 독립된 공간에 들어가는 설정과는 다르다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-000814/index.html"},{"id":"MEJE-KW-000815","row_version":1,"title":"자연스럽게 하려다 더 어색해지기","original":"Acting Unnatural","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"들키지 말고 평소처럼 행동하라는 말을 의식한 인물이 오히려 과장된 표정과 몸짓을 보여 정체를 드러내는 장면. 행동을 통제하려는 의도가 실수를 만든다. 상상을 실제 행동으로 옮겨 버리기는 의도보다 몰입이 몸짓을 바꾸는 경우다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-000815/index.html"},{"id":"MEJE-KW-000816","row_version":1,"title":"똑똑한 아이를 작은 어른처럼 그리기","original":"Acting Your Intellectual Age","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"어린 인물을 높은 지적 능력 때문에 또래의 놀이보다 어른의 말투와 관심사에 익숙한 모습으로 그리는 인물형. 지능과 삶의 경험을 같은 것으로 다루는지 살펴야 한다. 한 번의 시험이 미래를 결정하는 세계는 아이의 능력을 평가하는 사회 설정이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000816/index.html"},{"id":"MEJE-KW-000817","row_version":1,"title":"액션 어드벤처 게임","original":"Action-Adventure","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03","ML-T00428","ML-T00431"],"summary":"실시간 조작으로 위험을 넘기는 과정과 공간 탐색·도구 활용·퍼즐 해결을 한 흐름으로 묶은 게임 형식. 액션 게임의 순발력 중심 도전과 탐험의 발견감을 함께 쓰되 어느 요소가 핵심인지에 따라 작품의 성격이 달라진다.","accent":"#8A687E","tab":"#9B8A6F","facet":"장르","bookmark":"액션 어드벤처","entry_url":"cards/MEJE-KW-000817/index.html"},{"id":"MEJE-KW-000818","row_version":1,"title":"행동 명령 막대","original":"Action Bar","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25","ML-T02070"],"summary":"현재 실행할 수 있는 행동이나 장비를 화면의 가로·세로 칸에 모아 보여 주는 조작 인터페이스. 플레이어가 가능한 선택을 한눈에 확인하게 하지만, 메뉴가 과밀하면 장면 자체보다 명령 목록이 먼저 눈에 들어올 수 있다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"조작·행위","entry_url":"cards/MEJE-KW-000818/index.html"},{"id":"MEJE-KW-000819","row_version":1,"title":"액션 중심 임무","original":"Action-Based Mission","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"평소에는 잠입·탐색·대화 같은 방식으로 진행되던 게임이 특정 임무에서 속도와 전투를 주된 통과 조건으로 내세우는 구성. 익숙한 해결법을 잠시 바꾸어 긴장을 높일 수 있지만, 앞서 익힌 기술을 쓸 수 없게 만들면 흐름이 끊길 수도 있다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-000819/index.html"},{"id":"MEJE-KW-000820","row_version":1,"title":"자폭 전투원","original":"Action Bomb","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"자신의 폭발을 공격 수단으로 삼는 인물이나 생물. 목표에 바짝 접근한다는 특성 때문에 상대의 거리 판단을 시험하며, 죽은 뒤 폭발하는 유형은 승리 직후에도 위험이 남는 장면을 만든다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000820/index.html"},{"id":"MEJE-KW-000821","row_version":1,"title":"타이밍 명령","original":"Action Commands","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25","ML-T02070","ML-T02077"],"summary":"정해진 짧은 시간 안에 버튼이나 방향 입력을 맞추면 행동의 결과가 달라지는 게임 조작. 차례를 기다리는 전투에도 손의 리듬을 끌어들이며, 입력 실패를 어느 정도까지 벌할지가 난이도를 좌우한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"타이밍 입력","entry_url":"cards/MEJE-KW-000821/index.html"},{"id":"MEJE-KW-000822","row_version":1,"title":"전투하는 아버지","original":"Action Dad","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"가족에게 닥친 위협을 알아차린 뒤 직접 위험한 현장에 나서는 아버지 인물형. 보호자의 책임감과 행동 능력이 한 몸에 놓이지만, 자녀가 스스로 선택할 여지를 남기는지도 관계 묘사의 쟁점이 된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000822/index.html"},{"id":"MEJE-KW-000823","row_version":1,"title":"전투를 위해 옷 찢기","original":"Action Dress Rip","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"움직임을 방해하는 의상을 인물이 급히 찢거나 고쳐 즉시 행동할 수 있게 만드는 장면. 옷차림이 바뀌는 순간을 통해 일상적 역할에서 긴급한 대응으로 넘어갔음을 눈에 보이게 한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-000823/index.html"},{"id":"MEJE-KW-000824","row_version":1,"title":"전투원과 생존자 콤비","original":"Action Duo","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"싸움에 능숙한 인물과 위험에서 살아남는 재주가 앞서는 인물이 한 팀을 이루는 관계 구도. 서로의 부족한 능력을 메우는 동안 보호·의존·동료 의식의 균형이 바뀐다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-000824/index.html"},{"id":"MEJE-KW-000825","row_version":1,"title":"멋을 포기하지 않는 전투 인물","original":"Action Fashionista","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"격한 활동을 하면서도 옷차림의 변화와 꾸밈을 자기 표현의 일부로 유지하는 인물형. 단일 전투복보다 폭넓은 의상이 성격과 장면의 분위기를 전하며, 외형을 위해 기능을 얼마나 양보하는지도 설정에 따라 달라진다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-000825/index.html"},{"id":"MEJE-KW-000826","row_version":1,"title":"피규어 설정 카드","original":"Action Figure File Card","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27","ML-T02293","ML-T02297"],"summary":"캐릭터 완구의 포장이나 동봉 인쇄물에 인물의 신상·능력·배경을 짧게 적어 두는 소개 형식. 작은 상품 부속물이 이야기의 빈칸을 채우는 자료가 되며, 본편 밖에서 설정을 확장하는 통로로 쓰인다.","accent":"#7F8A85","tab":"#A07A87","facet":"메타·제작·유통","bookmark":"굿즈","entry_url":"cards/MEJE-KW-000826/index.html"},{"id":"MEJE-KW-000827","row_version":1,"title":"인형 대신 액션 피규어라 우기기","original":"Action Figure Justification","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23","ML-T01993"],"summary":"사람 모양의 장난감을 인형이라고 부르자 소유자가 굳이 액션 피규어라고 고쳐 부르는 말다툼. 물건의 실제 차이보다 취향이 어떻게 보일지를 의식하는 태도가 대사의 웃음이나 인물 묘사를 만든다.","accent":"#7C808E","tab":"#AF8665","facet":"서술·언어·정보","bookmark":"언어 장치","entry_url":"cards/MEJE-KW-000827/index.html"},{"id":"MEJE-KW-000828","row_version":1,"title":"입 없는 인물의 몸짓 대사","original":"Action Figure Speech","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22","ML-T01917","ML-T01921"],"summary":"입의 움직임을 보여 줄 수 없는 인물이 말할 때 머리나 온몸을 흔들어 발화 사실을 알리는 표현. 소리가 나는 지점이 보이지 않는 한계를 동작으로 메우며, 과장 정도에 따라 우스꽝스럽거나 기계적인 인상이 된다.","accent":"#688397","tab":"#6D7BA1","facet":"시각·공간 연출","bookmark":"과장된 움직임","entry_url":"cards/MEJE-KW-000828/index.html"},{"id":"MEJE-KW-000829","row_version":1,"title":"액션 서사의 고요한 대화 장면","original":"Action Film, Quiet Drama Scene","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"격렬한 사건 사이에 움직임을 줄이고 인물의 마음이나 목표를 대화로 드러내는 장면. 앞뒤의 큰 행동에 감정적 의미를 부여하며, 단순히 정보를 전달하는 설명 장면과 달리 관계나 가치 판단을 움직인다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-000829/index.html"},{"id":"MEJE-KW-000830","row_version":1,"title":"액션 게임","original":"Action Game","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03","ML-T00414"],"summary":"플레이어의 즉각적인 조작과 반응 속도를 주요 도전으로 삼는 게임 장르. 전투나 장애물 돌파가 중심이 되기 쉽지만, 액션 어드벤처 게임처럼 탐색·퍼즐과 결합하면 세부 분류가 달라진다.","accent":"#8A687E","tab":"#AF8665","facet":"장르","bookmark":"게임 장르·액션","entry_url":"cards/MEJE-KW-000830/index.html"},{"id":"MEJE-KW-000831","row_version":1,"title":"액션 장르","original":"Action Genre","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03","ML-T00198"],"summary":"추격·대결·탈출처럼 신체적 위험을 눈앞의 사건으로 밀어붙이는 이야기 장르. 무엇을 지키거나 얻어야 하는지가 행동의 이유를 만들고, 속도감 있는 장면의 연쇄가 긴장을 이어 간다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"액션","entry_url":"cards/MEJE-KW-000831/index.html"},{"id":"MEJE-KW-000832","row_version":1,"title":"흔한 액션 주인공","original":"Action Genre Hero Guy","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09","ML-T00880","ML-T00881"],"summary":"여러 액션 작품에서 비슷한 외모·태도·능력을 반복해 보여 주는 전형적 주인공상. 낯익은 기능을 빠르게 전달하지만, 작품만의 선택과 약점이 부족하면 인물의 구별감이 옅어진다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"주인공","entry_url":"cards/MEJE-KW-000832/index.html"},{"id":"MEJE-KW-000833","row_version":1,"title":"전투에 나서는 여성 인물","original":"Action Girl","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"위험 앞에서 다른 인물의 구조만 기다리지 않고 직접 싸우거나 돌파구를 만드는 여성 인물형. 유능함이 한 장면의 장식에 그치지 않으려면 선택과 결과가 자신의 서사에도 남아야 한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000833/index.html"},{"id":"MEJE-KW-000834","row_version":1,"title":"전투하는 여자친구","original":"Action Girlfriend","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"평범한 인물의 연인이지만 위험한 사건에서는 오히려 앞장서서 대응하는 여성 캐릭터와 그 관계 구도. 연인을 통해 사건 세계에 들어가는 시점 인물과 실제로 사건을 움직이는 인물 사이에 중심이 나뉠 수 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-000834/index.html"},{"id":"MEJE-KW-000835","row_version":1,"title":"액션 영웅","original":"Action Hero","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09","ML-T00899","ML-T00900"],"summary":"싸움과 물리적 행동을 문제 해결의 핵심 수단으로 쓰는 주인공형. 힘을 쓸 수 있는 상황뿐 아니라 그것을 선택해야 하는 이유와 대가를 보여 줄 때 행동에 인물의 뜻이 실린다. 우연히 생존하는 일반인은 위험을 피하며 버티는 쪽에서 출발한다.","accent":"#7B7594","tab":"#8B739C","facet":"인물","bookmark":"영웅","entry_url":"cards/MEJE-KW-000835/index.html"},{"id":"MEJE-KW-000836","row_version":1,"title":"액션 배우의 아이 돌봄 역할","original":"Action-Hero Babysitter","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27","ML-T02277","ML-T02278"],"summary":"거친 액션 배역으로 알려진 배우를 아이를 돌보는 인물로 배치하는 캐스팅 관습. 익숙한 배우 이미지와 낯선 돌봄 일이 만나는 어긋남이 웃음이나 새로운 면모를 만든다.","accent":"#7F8A85","tab":"#528982","facet":"메타·제작·유통","bookmark":"캐스팅 관행","entry_url":"cards/MEJE-KW-000836/index.html"},{"id":"MEJE-KW-000837","row_version":1,"title":"본편보다 화려한 액션 오프닝","original":"Action-Hogging Opening","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27","ML-T02277"],"summary":"작품의 제목 영상이나 도입부가 본편보다 훨씬 많은 움직임과 전투를 압축해 보여 주는 형식. 짧은 홍보성 장면이 작품의 실제 리듬에 대한 기대를 높이며, 그 차이가 감상 인상을 바꿀 수 있다.","accent":"#7F8A85","tab":"#528982","facet":"메타·제작·유통","bookmark":"제작 관행","entry_url":"cards/MEJE-KW-000837/index.html"},{"id":"MEJE-KW-000838","row_version":1,"title":"액션 호러 장르","original":"Action Horror","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03","ML-T00248"],"summary":"두려운 존재의 위협을 유지하면서도 인물이 맞서 싸울 능력과 수단을 갖춘 공포 이야기의 갈래. 대응 능력이 생긴 만큼 위협의 규모나 예측 불가능성을 키워 긴장을 이어 간다.","accent":"#8A687E","tab":"#528982","facet":"장르","bookmark":"공포","entry_url":"cards/MEJE-KW-000838/index.html"},{"id":"MEJE-KW-000839","row_version":1,"title":"행동 우선권","original":"Action Initiative","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"여러 참가자의 행동이 겹칠 때 어떤 행동을 먼저 처리할지 정하는 게임 규칙. 속도 수치와 선택한 행동의 특성이 차례를 바꾸면 같은 전투도 다른 판단을 요구한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-000839/index.html"},{"id":"MEJE-KW-000840","row_version":1,"title":"난장판 뒤 보험 걱정","original":"Action Insurance Gag","aliases":[],"kind":"keyword","facet_id":"ML-F19","node_kind":null,"parent_id":null,"tag_path":["ML-F19"],"summary":"추격이나 폭발로 재산이 망가진 순간 인물이 보험이나 수리비부터 걱정하는 농담. 큰 사건을 생활의 비용으로 갑자기 끌어내려 과장된 액션과 일상 감각 사이의 간격을 드러낸다.","accent":"#9B7F74","tab":"#9A6A55","facet":"정서·톤","bookmark":"분류축","entry_url":"cards/MEJE-KW-000840/index.html"},{"id":"MEJE-KW-000841","row_version":1,"title":"액션을 늘린 각색","original":"Actionized Adaptation","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28","ML-T02346","ML-T02347"],"summary":"원작에서는 대화나 추리·심리가 중심이던 장면을 다른 매체로 옮기며 추격과 전투 등 물리적 사건을 늘리는 각색. 장면의 규모가 커지는 만큼 원작의 긴장 방식도 새로 조정해야 한다.","accent":"#93856B","tab":"#7D8FA3","facet":"변주·관습","bookmark":"장르 전환","entry_url":"cards/MEJE-KW-000841/index.html"},{"id":"MEJE-KW-000842","row_version":1,"title":"속편에서 액션 강화","original":"Actionized Sequel","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28","ML-T02316"],"summary":"앞선 편보다 후속작이 전투·추격·폭발의 비중과 규모를 높이는 변화. 익숙한 인물을 새로운 위험에 놓을 수 있지만, 처음 작품의 장르적 중심을 어디까지 이어 갈지가 관건이 된다.","accent":"#93856B","tab":"#778F70","facet":"변주·관습","bookmark":"강도 조절","entry_url":"cards/MEJE-KW-000842/index.html"},{"id":"MEJE-KW-000843","row_version":1,"title":"싸우는 어머니","original":"Action Mom","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"자녀를 돌보는 역할과 위험한 현장에서 행동하는 역할을 함께 가진 어머니 인물형. 가족을 지키려는 마음만이 아니라 인물 자신의 목적과 능력도 사건 속에서 작동한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000843/index.html"},{"id":"MEJE-KW-000844","row_version":1,"title":"전투하는 반려동물","original":"Action Pet","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"반려동물이 보호 대상이나 귀여운 동행을 넘어 추격·구조·전투에 직접 참여하는 동료형 인물. 비인간 동반자의 행동이 사건의 해법을 바꾸며 주인과의 관계도 일방적인 보호에서 협력으로 옮겨 간다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000844/index.html"},{"id":"MEJE-KW-000845","row_version":1,"title":"직접 싸우는 정치인","original":"Action Politician","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"명령과 협상으로 사건을 움직이는 위치에 있으면서 위협 앞에서는 직접 몸을 던지는 정치인 인물형. 공적 권한과 개인의 전투 능력이 한 장면에 겹치면서 지도자의 책임을 색다르게 보여 준다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000845/index.html"},{"id":"MEJE-KW-000846","row_version":1,"title":"액션으로 시작하는 프롤로그","original":"Action Prologue","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"인물과 세계를 차근차근 설명하기 전에 먼저 위험한 사건을 보여 주는 도입 구성. 관객에게 앞으로의 긴장을 약속한 뒤 속도를 늦춰 사건의 배경과 인물을 소개한다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-000846/index.html"},{"id":"MEJE-KW-000848","row_version":1,"title":"액션 실시간 전략 게임","original":"Action RTS","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03","ML-T00442","ML-T00443"],"summary":"부대와 자원을 운영하는 실시간 전략에 한 인물을 직접 움직이는 액션 조작을 결합한 게임 형식. 지휘하는 시야와 전장 안의 몸을 오가며 어느 쪽의 판단을 먼저 할지 선택하게 한다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"실시간 전략","entry_url":"cards/MEJE-KW-000848/index.html"},{"id":"MEJE-KW-000849","row_version":1,"title":"액션 시리즈","original":"Action Series","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03","ML-T00198"],"summary":"회차마다 추격·대결·구출 같은 물리적 사건을 주요 볼거리로 삼는 연속물의 형식. 반복되는 인물과 임무가 이어지는 가운데 매 회의 위험과 해결 방식이 달라진다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"액션","entry_url":"cards/MEJE-KW-000849/index.html"},{"id":"MEJE-KW-000850","row_version":1,"title":"우연히 생존하는 일반인","original":"Action Survivor","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"전투 훈련이나 임무가 없는데 큰 위기에 휘말려 도망치고 판단하며 살아남는 인물형. 액션 영웅과 달리 준비된 힘보다 적응과 운, 주변 사람과의 협력이 행동의 출발점이 된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000850/index.html"},{"id":"MEJE-KW-000851","row_version":1,"title":"작동하는 유물을 두고 다투기","original":"Activating Artifact Tug-of-War","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"강한 힘을 가진 물건을 서로 빼앗으려는 와중에 누군가가 그것을 작동시키는 충돌 장면. 소유권 다툼과 사용의 결과가 한꺼번에 터져 승패보다 물건의 통제 가능성이 더 큰 문제가 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-000851/index.html"},{"id":"MEJE-KW-000852","row_version":1,"title":"기동 과정 보여주기","original":"Activation Sequence","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"장치나 시설이 켜질 때 빛·소리·움직임을 단계별로 보여 주는 연출. 기능을 설명하면서도 그것이 처음 살아나는 순간의 경이감이나 불길함을 관객에게 느끼게 한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-000852/index.html"},{"id":"MEJE-KW-000853","row_version":1,"title":"신념을 명분으로 타인 삶에 간섭하기","original":"Activist-Fundamentalist Antics","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"인물이 자신이 옳다고 믿는 주장을 내세워 타인의 자리와 삶에 무례하게 끼어드는 갈등. 이야기에서는 주장의 이름보다 실제 행동이 상대에게 어떤 피해를 남기는지 살펴야 인물을 구분할 수 있다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-000853/index.html"},{"id":"MEJE-KW-000854","row_version":1,"title":"파괴 공작","original":"Act of Sabotage","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"상대의 계획이나 시설이 제대로 작동하지 못하게 몰래 훼손하거나 방해하는 행동. 이야기에서는 결과를 누가 먼저 알아차리는지와 행위자의 목적이 밝혀지는 시점이 긴장을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-000854/index.html"},{"id":"MEJE-KW-000855","row_version":1,"title":"사랑을 증명하는 행동","original":"Act of True Love","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"소중한 사람의 안녕을 위해 자신의 시간·안전·기회를 기꺼이 내놓아 애정을 행동으로 보이는 순간. 연애뿐 아니라 가족과 친구 사이에서도 나타나며, 상대가 원하는 것을 존중하는지가 희생의 의미를 바꾼다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-000855/index.html"},{"id":"MEJE-KW-000856","row_version":1,"title":"배우의 전작을 암시하기","original":"Actor Allusion","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27","ML-T02277"],"summary":"새 작품 속 대사나 몸짓에 배우가 앞서 맡았던 배역을 떠올리게 하는 작은 단서를 넣는 제작 관습. 이전 작품을 아는 관객에게만 추가 의미가 열리며 본편의 사건은 그 단서 없이도 이해된다.","accent":"#7F8A85","tab":"#528982","facet":"메타·제작·유통","bookmark":"제작 관행","entry_url":"cards/MEJE-KW-000856/index.html"},{"id":"MEJE-KW-000857","row_version":1,"title":"배우 사망 뒤 인물 퇴장","original":"Actor Dies, Character Leaves","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27","ML-T02277"],"summary":"배우가 세상을 떠난 뒤 작품 속 인물은 살아 있는 설정을 유지하되 화면에서 더는 등장시키지 않는 제작 결정. 부재를 설명하는 방식은 남은 인물들의 애도와 이야기의 연속성에 영향을 준다.","accent":"#7F8A85","tab":"#528982","facet":"메타·제작·유통","bookmark":"제작 관행","entry_url":"cards/MEJE-KW-000857/index.html"},{"id":"MEJE-KW-000858","row_version":1,"title":"성우 부재로 인물 대사 중단","original":"Actor Existence Limbo","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27","ML-T02277"],"summary":"성우가 참여하지 못하게 되었지만 배역을 교체하지도 않아 애니메이션이나 게임의 인물이 말하지 못하는 상태. 인물의 존재는 이어지지만 표현 수단이 제한되어 화면 밖 처리나 과거 음성의 재사용을 고민하게 된다.","accent":"#7F8A85","tab":"#528982","facet":"메타·제작·유통","bookmark":"제작 관행","entry_url":"cards/MEJE-KW-000858/index.html"},{"id":"MEJE-KW-000859","row_version":1,"title":"배우에게서 온 작품 요소","original":"Actor-Inspired Element","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27","ML-T02277"],"summary":"배우의 제안이나 실제 성격·습관에서 출발한 의상, 말투, 소품 등이 작품의 인물 설정에 반영되는 제작 과정. 현장의 우연이 최종 화면의 고정된 특징이 되기도 한다.","accent":"#7F8A85","tab":"#528982","facet":"메타·제작·유통","bookmark":"제작 관행","entry_url":"cards/MEJE-KW-000859/index.html"},{"id":"MEJE-KW-000860","row_version":1,"title":"배우 해석으로 선해진 인물","original":"Actor-Inspired Heroism","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27","ML-T02277"],"summary":"대본에서 차갑거나 적대적으로 짜였던 인물이 배우의 연기를 거치며 더 공감할 만한 존재로 보이는 변화. 제작진이 그 인상을 뒤의 이야기에도 반영하면 인물의 역할 자체가 달라질 수 있다.","accent":"#7F8A85","tab":"#528982","facet":"메타·제작·유통","bookmark":"제작 관행","entry_url":"cards/MEJE-KW-000860/index.html"},{"id":"MEJE-KW-000861","row_version":1,"title":"제목 인물을 배우와 동일시하는 홍보","original":"Actor IS the Title Character","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27","ML-T02293","ML-T02295"],"summary":"포스터나 예고 문구에서 배우가 제목 속 인물 그 자체인 것처럼 이름을 강조하는 홍보 표현. 유명 배우의 이미지와 배역을 겹쳐 보여 관객이 작품을 기억하는 방식을 유도한다.","accent":"#7F8A85","tab":"#A07A87","facet":"메타·제작·유통","bookmark":"포스터","entry_url":"cards/MEJE-KW-000861/index.html"},{"id":"MEJE-KW-000862","row_version":1,"title":"배우 하차로 인물 사망","original":"Actor Leaves, Character Dies","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27","ML-T02277"],"summary":"배우가 작품을 떠나면서 그가 맡은 인물을 이야기 안에서 사망 처리하는 제작 선택. 배우 사망 뒤 인물 퇴장처럼 배우의 사망을 다루는 경우와 이유와 서사 효과를 구분한다.","accent":"#7F8A85","tab":"#528982","facet":"메타·제작·유통","bookmark":"제작 관행","entry_url":"cards/MEJE-KW-000862/index.html"},{"id":"MEJE-KW-000863","row_version":1,"title":"배우가 직접 연주하는 공연","original":"Actor-Muso Show","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26","ML-T02175"],"summary":"무대의 배우가 배역을 연기하면서 노래의 반주 악기도 직접 연주하는 공연 형식. 악기 연주가 극중 행동인지 무대의 음악인지는 장면마다 달라질 수 있다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"무대 구성","entry_url":"cards/MEJE-KW-000863/index.html"},{"id":"MEJE-KW-000864","row_version":1,"title":"실제 친척 역을 맡은 배우","original":"Actor Plays Their Own Relative","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27","ML-T02277","ML-T02278"],"summary":"배우가 실제 가족이나 조상, 친척에 해당하는 사람의 배역을 맡는 캐스팅. 외형과 말투의 닮음이 효과가 될 수 있지만 실제 관계와 작품 속 인물 해석은 별도로 다뤄야 한다.","accent":"#7F8A85","tab":"#528982","facet":"메타·제작·유통","bookmark":"캐스팅 관행","entry_url":"cards/MEJE-KW-000864/index.html"},{"id":"MEJE-KW-000865","row_version":1,"title":"배우와 배역을 혼동하는 팬","original":"Actor/Role Confusion","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"이야기 속 팬이 배우와 그가 연기한 허구 인물을 같은 사람처럼 대하는 상황. 작품 밖 인물의 현실과 배역의 사건을 혼동하는 정도가 갈등이나 웃음을 만든다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-000865/index.html"},{"id":"MEJE-KW-000866","row_version":1,"title":"배우의 실제 배경을 닮은 배역","original":"Actor-Shared Background","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27","ML-T02277","ML-T02278"],"summary":"배역의 성장 환경이나 경험 일부가 연기자의 실제 이력과 닮아 있는 캐스팅·설정 관계. 닮은 점은 표현에 도움을 줄 수 있지만 배우의 삶 전체를 인물의 설명으로 대신해서는 안 된다.","accent":"#7F8A85","tab":"#528982","facet":"메타·제작·유통","bookmark":"캐스팅 관행","entry_url":"cards/MEJE-KW-000866/index.html"},{"id":"MEJE-KW-000867","row_version":1,"title":"배우 커플 상상하기","original":"Actor Shipping","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27","ML-T02301","ML-T02304"],"summary":"팬이 작품 속 두 인물의 관계를 계기로 실제 배우들 사이에도 연애 관계가 있기를 상상하는 팬 활동. 허구의 놀이와 실존 인물의 사생활은 경계가 달라, 공개된 사실처럼 단정하지 않는 태도가 중요하다.","accent":"#7F8A85","tab":"#79866C","facet":"메타·제작·유통","bookmark":"커플링 해석","entry_url":"cards/MEJE-KW-000867/index.html"},{"id":"MEJE-KW-000869","row_version":1,"title":"패배한 것은 대역이었다","original":"Actually a Doombot","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"강한 인물이 패배하거나 죽은 듯 보인 뒤 진짜 본인은 현장에 없었고 닮은 대역이나 기계가 대신 있었다고 밝히는 반전. 인물을 다시 등장시킬 수 있지만 앞선 승리의 의미를 약하게 만들 수도 있다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-000869/index.html"},{"id":"MEJE-KW-000870","row_version":1,"title":"무시했던 제안이 좋은 생각이었다","original":"Actually a Good Idea","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"가볍게 여기던 사람의 제안을 듣고 다른 인물이 예상 밖의 쓸모를 인정하는 순간. 말한 사람에 대한 선입견과 제안 자체의 가치를 분리하면서 관계의 힘이 잠시 뒤집힌다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-000870/index.html"},{"id":"MEJE-KW-000871","row_version":1,"title":"한 적 표시 뒤에 여러 명","original":"Actually Four Mooks","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25","ML-T02106"],"summary":"이동 화면에서는 적 하나로 보였는데 전투에 들어가면 여러 적이 나타나는 게임 표현. 전투 전에는 정확한 규모를 감추어 조우의 긴장을 만들고, 화면마다 다른 인원 표시 방식을 드러낸다.","accent":"#667E94","tab":"#528982","facet":"게임·상호작용","bookmark":"전투·경쟁","entry_url":"cards/MEJE-KW-000871/index.html"},{"id":"MEJE-KW-000872","row_version":1,"title":"찾던 사람이 바로 눈앞에 있었다","original":"Actually, I Am Him","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"어떤 사람을 찾던 인물이 낯선 이와 대화하다 그가 바로 찾던 당사자였음을 알게 되는 전개. 신원을 숨긴 이유와 그동안 오간 말이 밝혀진 뒤 관계의 의미가 바뀐다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-000872/index.html"},{"id":"MEJE-KW-000873","row_version":1,"title":"흡혈귀로 오해받은 다른 존재","original":"Actually Not a Vampire","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"햇빛 회피나 피에 대한 소문 때문에 흡혈귀로 의심받던 인물이 사실은 다른 정체를 가졌다는 반전. 익숙한 단서를 이용해 추측을 유도한 뒤 같은 현상을 새 규칙으로 설명한다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-000873/index.html"},{"id":"MEJE-KW-000874","row_version":1,"title":"싫어도 웃게 되는 농담","original":"Actually Pretty Funny","aliases":[],"kind":"keyword","facet_id":"ML-F19","node_kind":null,"parent_id":null,"tag_path":["ML-F19"],"summary":"마음에 들지 않는 사람이 한 말인데도 웃음을 참지 못하는 장면. 대립 관계가 유지되면서도 유머의 효과만큼은 인정하게 되어 인물 사이에 짧은 틈이 생긴다.","accent":"#9B7F74","tab":"#9A6A55","facet":"정서·톤","bookmark":"분류축","entry_url":"cards/MEJE-KW-000874/index.html"},{"id":"MEJE-KW-000875","row_version":1,"title":"뜻밖에도 감탄할 만한 성과","original":"Actually Pretty Impressive","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"낮게 보던 인물의 행동이나 결과를 보고 상대가 실력을 인정하는 반응. 칭찬을 받아들일지는 별개이며, 평가하던 쪽의 태도 변화가 장면의 핵심이다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-000875/index.html"},{"id":"MEJE-KW-000876","row_version":1,"title":"미워도 따라 부르게 되는 노래","original":"Actually Quite Catchy","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"노래를 만든 사람이나 가사를 싫어하는 인물마저 멜로디를 흥얼거리게 되는 장면. 음악의 전염성과 인물의 의식적인 거부가 충돌해 웃음을 만든다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-000876/index.html"},{"id":"MEJE-KW-000877","row_version":1,"title":"상사로 착각한 사람이 조수였다","original":"Actually, That's My Assistant","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"권위 있어 보이는 사람을 책임자로 지목했지만 실제 책임자는 옆의 다른 인물인 상황. 옷차림이나 나이 같은 겉모습으로 지위를 추정한 인물의 선입견이 드러난다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-000877/index.html"},{"id":"MEJE-KW-000878","row_version":1,"title":"끝까지 폭력을 거부하는 인물","original":"Actual Pacifist","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"자기 방어가 필요해 보이는 상황에서도 다른 사람을 해치는 행동을 거부하는 인물형. 선택의 대가와 비폭력으로 위험에 대응하는 방법이 함께 그려져야 신념이 단순한 구호를 넘는다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000878/index.html"},{"id":"MEJE-KW-000879","row_version":1,"title":"TRPG 실황 콘텐츠","original":"Actual Play","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":null,"parent_id":null,"tag_path":["ML-F02","ML-T00084"],"summary":"사람들이 탁상 역할수행게임을 플레이하는 과정 자체를 관객에게 보여 주거나 들려주는 콘텐츠 형식. 규칙에 따른 선택과 즉흥적인 연기가 함께 이야기를 만들며 편집과 진행 방식에 따라 감상 리듬이 달라진다. 테이블톱 게임과 연결된다.","accent":"#55758A","tab":"#80906E","facet":"미디어","bookmark":"테이블톱 게임","entry_url":"cards/MEJE-KW-000879/index.html"},{"id":"MEJE-KW-000880","row_version":1,"title":"마지막 생존자로 종족 재건하기","original":"Adam and Eve Plot","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"멸종 위기에 놓인 집단의 마지막 생존자를 보호하고 뒤를 이을 세대를 만드는 것을 목표로 삼는 이야기 구조. 두 사람만으로 재건이 가능하다는 설정은 현실 생물학과 별개의 허구 규칙으로 다뤄야 한다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-000880/index.html"},{"id":"MEJE-KW-000881","row_version":1,"title":"아담과 이브 이름의 기원 상징","original":"Adam and/or Eve","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"인물에게 아담이나 이브라는 이름을 주어 첫 사람, 새 시작, 종말 뒤의 재출발 같은 이미지를 불러오는 명명 방식. 이름만 같다고 자동으로 상징이 되는 것은 아니며 작품 안의 역할과 연결되어야 한다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-000881/index.html"},{"id":"MEJE-KW-000882","row_version":1,"title":"플레이어에게 유독 불리한 물가","original":"Adam Smith Hates Your Guts","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25","ML-T02097"],"summary":"게임 속 상점이 플레이어가 필요로 하는 물건에 과도한 값을 붙이거나 진행할수록 가격을 비정상적으로 올리는 경제 규칙. 자원 부족을 도전으로 만들지만 세계의 거래 논리와 어긋나면 인위적인 제약으로 느껴진다.","accent":"#667E94","tab":"#A58A4E","facet":"게임·상호작용","bookmark":"경제·자원","entry_url":"cards/MEJE-KW-000882/index.html"}]}.cards;